88	func TestNormalizeCanonicalNames(t *testing.T) {
89		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"logout"}`
90		results := runNormalize(t, input)
91		event := eventOf(t, results[0])
92		if event["timestamp"] != "2026-01-02T00:00:00Z" || event["action"] != "logout" {
93			t.Fatalf("unexpected event: %#v", event)
94		}
95		if _, exists := event["source_ip"]; exists {
96			t.Fatalf("absent source_ip must not be serialized")
97		}
98		if _, exists := event["extra"]; exists {
99			t.Fatalf("empty extra must not be serialized")
100		}
101	}
