246	func TestNormalizeInvalidAliasFailsEvenWhenRewritable(t *testing.T) {
247		// The single-digit-hour alias denotes the same instant as the legal
248		// timestamp, but validity is checked per field first: the illegal
249		// spelling must fail the whole line, never be padded and then merged.
250		input := `{"timestamp":"2026-01-02T15:04:05Z","time":"2026-01-02T15:04:05,1Z","action":"a"}`
251		results := runNormalize(t, input)
252		if results[0]["ok"] != false {
253			t.Fatalf("comma-fraction alias must fail despite denoting the same instant: %#v", results[0])
254		}
255		input = `{"timestamp":"2026-01-02T15:04:05Z","time":"2026-01-02T16:04:05+00:60","action":"a"}`
256		results = runNormalize(t, input)
257		if results[0]["ok"] != false {
258			t.Fatalf("carried offset alias must fail despite denoting the same instant: %#v", results[0])
259		}
260		msg, _ := results[0]["error"].(string)
261		if !strings.Contains(msg, FieldTimestamp) {
262			t.Fatalf("error must name %q, got %q", FieldTimestamp, msg)
263		}
264	}
