266	func TestNormalizeStrictTimestampPreserves(t *testing.T) {
267		ok := map[string]string{
268			// Fractional precision is kept and trailing zeros dropped across zones.
269			"2026-01-02T23:04:05.100000000+08:00": "2026-01-02T15:04:05.1Z",
270			"2026-01-02T15:04:05.000000001Z":      "2026-01-02T15:04:05.000000001Z",
271			// Boundary-valid offsets must stay accepted after the range checks.
272			"2026-01-02T15:04:05+23:59": "2026-01-01T15:05:05Z",
273			"2026-01-02T15:04:05-23:59": "2026-01-03T15:03:05Z",
274			"2026-01-02T15:04:05+00:00": "2026-01-02T15:04:05Z",
275		}
276		for in, want := range ok {
277			results := runNormalize(t, `{"timestamp":"`+in+`","action":"a"}`)
