480		if results[1]["line"] != float64(4) || results[1]["ok"] != false {
481			t.Fatalf("bad input is physical line 4, got: %#v", results[1])
482		}
483		if results[2]["line"] != float64(6) || results[2]["ok"] != true {
484			t.Fatalf("valid line 6 must still be processed, got: %#v", results[2])
485		}
486		if eventOf(t, results[2])["action"] != "b" {
487			t.Fatalf("input order not preserved")
488		}
489	}
