491	func TestNormalizeNoFinalNewline(t *testing.T) {
492		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a"}`
493		results := runNormalize(t, input)
494		if len(results) != 1 || results[0]["ok"] != true {
495			t.Fatalf("final line without newline must still process: %#v", results)
496		}
497	}
