499	func TestNormalizeEmptyAndBlankInput(t *testing.T) {
500		for _, input := range []string{"", "\n", "  \n\n\t\n"} {
501			var out bytes.Buffer
502			failures, err := NormalizeReader(strings.NewReader(input), &out)
503			if err != nil || failures != 0 {
504				t.Fatalf("blank input must be clean, got failures=%d err=%v", failures, err)
505			}
506			if out.Len() != 0 {
507				t.Fatalf("blank input must produce no output, got %q", out.String())
508			}
509		}
510	}
