512	func TestNormalizeDeterministic(t *testing.T) {
513		input := strings.Join([]string{
514			`{"src_ip":"2001:DB8::1","time":"2026-01-02T08:04:05.123456789+08:00","event_type":" login ","device":{"os":["linux",null],"v":3}}`,
515			`{"time":"2026-01-02T00:00:00Z","timestamp":"2026-01-02T01:00:00Z","action":"x"}`,
516			`{"timestamp":"bad","action":"x"}`,
517			`null`,
518			`{"time":"2026-01-02T00:00:00Z","action":"y"}`,
519		}, "\n")
520		var first bytes.Buffer
521		if _, err := NormalizeReader(strings.NewReader(input), &first); err != nil {
522			t.Fatal(err)
523		}
524		for i := 0; i < 5; i++ {
525			var again bytes.Buffer
526			if _, err := NormalizeReader(strings.NewReader(input), &again); err != nil {
527				t.Fatal(err)
528			}
529			if again.String() != first.String() {
530				t.Fatalf("normalization is not deterministic on iteration %d", i)
531			}
532		}
533		if strings.Contains(first.String(), "0001-01-01") {
534			t.Fatalf("output must not synthesize a zero/current timestamp")
535		}
536	}
