538	func TestNormalizeUTCYearRange(t *testing.T) {
539		// Legal four-digit-year inputs whose UTC conversion escapes 0000-9999
540		// must fail; RFC3339Nano cannot represent the result and detection
541		// rules must never receive an out-of-range canonical timestamp.
542		outOfRange := []string{
543			"0000-01-01T00:00:00+00:01",
544			"0000-01-01T00:00:59+01:00",
545			"0000-01-01T00:00:00+23:59", // largest legal offset: lands in year -1
546			"9999-12-31T23:59:59-00:01",
547			"9999-12-31T23:00:00-01:00",
548			"9999-12-31T23:59:00-23:59",
549		}
550		for _, in := range outOfRange {
551			for _, wrapper := range []string{
552				`{"timestamp":"` + in + `","action":"a"}`,
553				`{"time":"` + in + `","action":"a"}`,
554			} {
555				results := runNormalize(t, wrapper)
556				if results[0]["ok"] != false {
557					t.Fatalf("timestamp %q must fail after UTC conversion, got %#v", in, results[0])
558				}
559				if _, exists := results[0]["event"]; exists {
560					t.Fatalf("out-of-range timestamp %q must not emit an event", in)
561				}
562				msg, _ := results[0]["error"].(string)
563				if !strings.Contains(msg, FieldTimestamp) {
564					t.Fatalf("error for %q must name %q, got %q", in, FieldTimestamp, msg)
565				}
566				if !strings.Contains(msg, "UTC year") || !strings.Contains(msg, "0000-9999") {
567					t.Fatalf("error for %q must state the UTC year range, got %q", in, msg)
568				}
569			}
570		}
571	
572		// The range endpoints are inclusive and fractional precision must
573		// survive at the edges, with trailing zeros still trimmed.
574		ok := map[string]string{
575			"0000-01-01T00:00:00Z":             "0000-01-01T00:00:00Z",
576			"0000-01-01T00:01:00+00:01":        "0000-01-01T00:00:00Z",
577			"0000-01-01T00:00:00-23:59":        "0000-01-01T23:59:00Z",
578			"0000-01-01T00:00:00.123456+00:00": "0000-01-01T00:00:00.123456Z",
579			"9999-12-31T23:59:59Z":             "9999-12-31T23:59:59Z",
580			"9999-12-31T23:58:59-00:01":        "9999-12-31T23:59:59Z",
581			"9999-12-31T23:59:59.100000000Z":   "9999-12-31T23:59:59.1Z",
582			"9999-12-31T23:59:59.000000001Z":   "9999-12-31T23:59:59.000000001Z",
583		}
584		for in, want := range ok {
585			results := runNormalize(t, `{"timestamp":"`+in+`","action":"a"}`)
586			if results[0]["ok"] != true {
587				t.Fatalf("boundary timestamp %q should succeed, got %#v", in, results[0])
588			}
589			if got := eventOf(t, results[0])["timestamp"]; got != want {
590				t.Fatalf("timestamp %q -> %v, want %q", in, got, want)
591			}
592		}
593	}
594	
595	func TestNormalizeUTCYearRangeAliases(t *testing.T) {
596		cases := []struct {
597			name  string
598			input string
599			ok    bool
600			want  string
601		}{
602			{
603				name:  "same out-of-range instant spelled twice",
604				input: `{"timestamp":"0000-01-01T00:00:00+00:01","time":"0000-01-01T00:01:00+00:02","action":"a"}`,
605				ok:    false,
606			},
607			{
608				name:  "same out-of-range instant repeated",
609				input: `{"timestamp":"9999-12-31T23:59:59-00:01","time":"9999-12-31T23:59:59-00:01","action":"a"}`,
610				ok:    false,
611			},
612			{
613				name:  "one legal value one out of range",
614				input: `{"timestamp":"0000-01-01T00:00:00Z","time":"0000-01-01T00:00:00+00:01","action":"a"}`,
615				ok:    false,
616			},
617			{
618				name:  "legal consistent values at lower edge merge",
619				input: `{"timestamp":"0000-01-01T00:00:00Z","time":"0000-01-01T00:01:00+00:01","action":"a"}`,
620				ok:    true,
621				want:  "0000-01-01T00:00:00Z",
622			},
623			{
624				name:  "legal consistent values at upper edge merge",
625				input: `{"timestamp":"9999-12-31T23:59:59Z","time":"9999-12-31T23:58:59-00:01","action":"a"}`,
626				ok:    true,
627				want:  "9999-12-31T23:59:59Z",
628			},
629			{
630				name:  "distinct legal instants still conflict",
631				input: `{"timestamp":"0000-01-01T00:01:00+00:01","time":"0000-01-01T00:02:00+00:01","action":"a"}`,
632				ok:    false,
633			},
634		}
635		for _, tc := range cases {
636			t.Run(tc.name, func(t *testing.T) {
637				results := runNormalize(t, tc.input)
638				if tc.ok {
639					if results[0]["ok"] != true {
640						t.Fatalf("expected success, got %#v", results[0])
641					}
642					if got := eventOf(t, results[0])["timestamp"]; got != tc.want {
643						t.Fatalf("timestamp %v, want %q", got, tc.want)
644					}
645					return
646				}
647				if results[0]["ok"] != false {
648					t.Fatalf("expected failure, got %#v", results[0])
649				}
650				if _, exists := results[0]["event"]; exists {
651					t.Fatalf("failure must not emit an event")
652				}
653				msg, _ := results[0]["error"].(string)
654				if !strings.Contains(msg, FieldTimestamp) {
655					t.Fatalf("error must name %q, got %q", FieldTimestamp, msg)
656				}
657			})
658		}
659	}
660	
661	func TestNormalizeUTCYearRangeMixedStream(t *testing.T) {
662		// The year-range error is a single-line failure: surrounding legal
663		// lines still come out in order with their physical line numbers,
664		// blank lines only advance the counter, and the run reports the
665		// failure count (which drives exit status 1 in the CLI).
666		input := "{\"timestamp\":\"0000-01-01T00:01:00+00:01\",\"action\":\"a\"}\n" +
667			"\n" +
668			"{\"timestamp\":\"0000-01-01T00:00:00+00:01\",\"action\":\"b\"}\n" +
669			"   \n" +
670			"{\"timestamp\":\"9999-12-31T23:59:59-00:01\",\"action\":\"c\"}\n" +
671			"{\"timestamp\":\"9999-12-31T23:59:59Z\",\"action\":\"d\"}\n"
672		results := runNormalize(t, input)
673		if len(results) != 4 {
674			t.Fatalf("expected 4 results for 6 physical lines, got %d: %#v", len(results), results)
675		}
676		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
677			t.Fatalf("line 1 must succeed: %#v", results[0])
678		}
679		if got := eventOf(t, results[0])["timestamp"]; got != "0000-01-01T00:00:00Z" {
680			t.Fatalf("line 1 timestamp %v", got)
681		}
682		if results[1]["line"] != float64(3) || results[1]["ok"] != false {
683			t.Fatalf("line 3 must fail preserving its line number: %#v", results[1])
684		}
685		if results[2]["line"] != float64(5) || results[2]["ok"] != false {
686			t.Fatalf("line 5 must fail preserving its line number: %#v", results[2])
687		}
688		if results[3]["line"] != float64(6) || results[3]["ok"] != true {
689			t.Fatalf("legal line 6 must still be processed: %#v", results[3])
690		}
691		if eventOf(t, results[3])["action"] != "d" {
692			t.Fatalf("input order not preserved")
693		}
