func TestNormalizeWrongTypes(t *testing.T) {
	cases := []string{
		`{"timestamp":1735689600,"action":"a"}`,
		`{"timestamp":true,"action":"a"}`,
		`{"timestamp":["2026-01-02T00:00:00Z"],"action":"a"}`,
