	if event["timestamp"] != "2026-01-02T00:04:05Z" {
		t.Fatalf("timestamp mismatch: %v", event["timestamp"])
	}
	if event["source_ip"] != "::1" {
		t.Fatalf("source_ip mismatch: %v", event["source_ip"])
