		`{"action":"a" "x":"y"}`,
	}
	for _, in := range cases {
		results := runNormalize(t, in)
		if len(results) != 1 || results[0]["ok"] != false {
			t.Fatalf("non-object/syntax input must yield one failure: %s -> %#v", in, results)
		}
