46	// NormalizeResult is emitted for every non-blank input line, in input order.
47	type NormalizeResult struct {
48		Line  int              `json:"line"`
49		OK    bool             `json:"ok"`
50		Event *NormalizedEvent `json:"event,omitempty"`
51		Error string           `json:"error,omitempty"`
52	}
53	
54	type fieldCandidate struct {
55		from string
56		raw  json.RawMessage
57	}
58	
59	// NormalizeReader streams newline-delimited JSON logs from r and writes one
60	// NormalizeResult JSON object per non-blank physical line to w. Blank lines
61	// produce no output but still advance the physical line counter. It returns
62	// the number of lines that failed normalization; processing of later lines
63	// continues after any per-line failure.
64	func NormalizeReader(r io.Reader, w io.Writer) (failures int, err error) {
65		reader := bufio.NewReader(r)
66		bw := bufio.NewWriter(w)
67		defer func() {
68			if flushErr := bw.Flush(); err == nil {
69				err = flushErr
70			}
71		}()
72		encoder := json.NewEncoder(bw)
73		encoder.SetEscapeHTML(false)
74	
75		lineNo := 0
76		for {
77			line, readErr := reader.ReadBytes('\n')
78			if len(line) > 0 {
79				lineNo++
80				if strings.TrimSpace(string(line)) != "" {
81					result := NormalizeLine(lineNo, line)
82					if !result.OK {
83						failures++
84					}
85					if encErr := encoder.Encode(result); encErr != nil {
86						return failures, encErr
87					}
88				}
89			}
90			if readErr != nil {
91				if errors.Is(readErr, io.EOF) {
92					return failures, nil
93				}
94				return failures, readErr
95			}
96		}
97	}
