99	// NormalizeLine normalizes a single raw JSON log line. The line number is
100	// echoed unchanged in the result.
101	func NormalizeLine(lineNo int, raw []byte) NormalizeResult {
102		event, err := normalizeEvent(bytes.TrimSpace(raw))
103		if err != nil {
104			return NormalizeResult{Line: lineNo, OK: false, Error: err.Error()}
105		}
106		return NormalizeResult{Line: lineNo, OK: true, Event: event}
107	}
