123		groups := make(map[string][]fieldCandidate)
124		extra := make(map[string]json.RawMessage)
125		for _, key := range keys {
126			switch key {
127			case FieldTimestamp, FieldSourceIP, FieldAction:
128				groups[key] = append(groups[key], fieldCandidate{from: key, raw: object[key]})
129			default:
130				if canonical, ok := fieldAliases[key]; ok {
131					groups[canonical] = append(groups[canonical], fieldCandidate{from: key, raw: object[key]})
132				} else {
133					extra[key] = object[key]
134				}
135			}
136		}
137	
138		values := make(map[string]string)
139		for _, canonical := range canonicalFieldOrder {
140			candidates := groups[canonical]
141			if len(candidates) == 0 {
142				continue
143			}
144			var canonicalValue string
145			for i, candidate := range candidates {
146				value, err := normalizeFieldValue(canonical, candidate.raw)
147				if err != nil {
148					return nil, err
149				}
150				if i == 0 {
151					canonicalValue = value
