155				// divergent values fail the whole line.
156				if value != canonicalValue {
157					return nil, fmt.Errorf("field %q has conflicting values: %q and %q", canonical, canonicalValue, value)
158				}
159			}
160			values[canonical] = canonicalValue
161		}
