163		timestamp, ok := values[FieldTimestamp]
164		if !ok {
165			return nil, fmt.Errorf("missing required field %q", FieldTimestamp)
166		}
167		action, ok := values[FieldAction]
168		if !ok {
169			return nil, fmt.Errorf("missing required field %q", FieldAction)
170		}
171	
172		event := &NormalizedEvent{
173			Timestamp: timestamp,
174			Action:    action,
175		}
176		if sourceIP, present := values[FieldSourceIP]; present {
177			event.SourceIP = sourceIP
178		}
179		if len(extra) > 0 {
180			event.Extra = extra
181		}
182		return event, nil
183	}
184	
185	// decodeObject parses one JSON object and rejects duplicate top-level keys,
186	// including when the repeated key carries the same value.
187	func decodeObject(raw []byte) (map[string]json.RawMessage, error) {
188		decoder := json.NewDecoder(bytes.NewReader(raw))
189		token, err := decoder.Token()
190		if err != nil {
191			return nil, fmt.Errorf("invalid JSON: %v", err)
192		}
193		delim, ok := token.(json.Delim)
194		if !ok || delim != '{' {
195			return nil, errors.New("log must be a JSON object")
196		}
197	
198		object := make(map[string]json.RawMessage)
199		for decoder.More() {
200			keyToken, err := decoder.Token()
201			if err != nil {
202				return nil, fmt.Errorf("invalid JSON: %v", err)
203			}
204			key := keyToken.(string)
205			var value json.RawMessage
206			if err := decoder.Decode(&value); err != nil {
207				return nil, fmt.Errorf("invalid JSON in field %q: %v", key, err)
208			}
209			if _, exists := object[key]; exists {
210				return nil, fmt.Errorf("duplicate field %q", key)
211			}
212			object[key] = value
213		}
214		if _, err := decoder.Token(); err != nil { // consume closing '}'
215			return nil, fmt.Errorf("invalid JSON: %v", err)
216		}
217		if tok, err := decoder.Token(); !errors.Is(err, io.EOF) {
218			if err == nil {
219				return nil, fmt.Errorf("invalid JSON: unexpected trailing token %s", tok)
220			}
221			return nil, fmt.Errorf("invalid JSON: %v", err)
222		}
223		return object, nil
